package co.edu.cinematch.core.model;
public class Cine implements Identifiable { private String id; private String nombre; private String direccion; private String ciudad; public Cine(){} public Cine(String nombre,String direccion,String ciudad){this.nombre=nombre;this.direccion=direccion;this.ciudad=ciudad;} public String getId(){return id;}public void setId(String v){id=v;}public String getNombre(){return nombre;}public void setNombre(String v){nombre=v;}public String getDireccion(){return direccion;}public void setDireccion(String v){direccion=v;}public String getCiudad(){return ciudad;}public void setCiudad(String v){ciudad=v;} }
